// convex/forecasts.ts
// Moving-average energy forecasts — generated by cron, read by dashboard.
//
// Method: for each hour of the day (WAT), average the hub's total power over the
// last 7 days, then predict that average for the same hour over the next 24 h.
// One hour at an average of P watts = P/1000 kWh. This is a simple baseline
// estimate, not a validated model.

import { v } from "convex/values";
import { internalMutation, query } from "./_generated/server";
import { internal } from "./_generated/api";
import { getHubReadAccess } from "./access";

const DAYS_BACK        = 7;
const FORECAST_HOURS   = 24;
const SAMPLES_PER_HOUR = 60;      // readings sampled per historical hour (bounded reads)
const ACTIVE_WINDOW_MS = 48 * 3600 * 1000;

// ── Internal: cron entry point — schedule one forecast per recently active hub ──
// Each hub runs in its own transaction so one failure can't block the others.
export const generateForAllHubs = internalMutation({
  args: {},
  handler: async (ctx) => {
    const cutoff = Date.now() - ACTIVE_WINDOW_MS;
    for await (const hub of ctx.db.query("hubs")) {
      if ((hub.lastSeenAt ?? 0) >= cutoff) {
        await ctx.scheduler.runAfter(0, internal.forecasts.generate, {
          hubId:  hub._id,
          userId: hub.userId,
        });
      }
    }
  },
});

// ── Internal: generate and store a 24-hour moving-average forecast ─────────
export const generate = internalMutation({
  args: {
    hubId:  v.id("hubs"),
    userId: v.id("users"),
  },
  handler: async (ctx, args) => {
    const nowSec = Math.floor(Date.now() / 1000);
    const firstHour = (Math.floor(nowSec / 3600) - DAYS_BACK * 24) * 3600;

    // Sample each past hour separately so reads stay bounded (168 × 60 max).
    const hourBuckets: number[][] = Array.from({ length: 24 }, () => []);
    for (let h = firstHour; h < nowSec; h += 3600) {
      const readings = await ctx.db
        .query("hubReadings")
        .withIndex("by_hub_time", (q) =>
          q.eq("hubId", args.hubId).gte("timestamp", h).lt("timestamp", h + 3600)
        )
        .take(SAMPLES_PER_HOUR);
      const watHour = Math.floor((h + 3600) / 3600) % 24;
      for (const r of readings) hourBuckets[watHour].push(r.totalPowerW);
    }

    if (hourBuckets.reduce((n, b) => n + b.length, 0) < 12) return;  // not enough data

    // Average and std-dev per hour
    const hourStats = hourBuckets.map((samples) => {
      if (samples.length === 0) return { mean: 0, std: 0, n: 0 };
      const mean = samples.reduce((s, v) => s + v, 0) / samples.length;
      const variance =
        samples.reduce((s, v) => s + Math.pow(v - mean, 2), 0) / samples.length;
      return { mean, std: Math.sqrt(variance), n: samples.length };
    });

    // Build 24 forecast data points, one per hour starting from the next full hour
    const nextHourSec = (Math.floor(nowSec / 3600) + 1) * 3600;
    const dataPoints = Array.from({ length: FORECAST_HOURS }, (_, i) => {
      const ts    = nextHourSec + i * 3600;
      const watH  = Math.floor((ts + 3600) / 3600) % 24;
      const stats = hourStats[watH];
      // An hour at an average of P watts is P / 1000 kWh.
      const kwhPerHour = stats.mean / 1000;
      const stdKwh     = stats.std  / 1000;
      return {
        timestamp:      ts,
        predictedKwh:   Math.round(kwhPerHour * 1000) / 1000,
        confidenceLow:  Math.round(Math.max(0, kwhPerHour - stdKwh) * 1000) / 1000,
        confidenceHigh: Math.round((kwhPerHour + stdKwh) * 1000) / 1000,
        samples:        stats.n,   // 0 = no history for this hour; the value is not a prediction
      };
    });

    await ctx.db.insert("forecasts", {
      hubId:        args.hubId,
      userId:       args.userId,
      generatedAt:  Date.now(),
      forecastType: "moving_average",
      dataPoints,
    });
  },
});

// ── Public: get the latest forecast for a hub ────────────────────────────
export const getLatest = query({
  args: { hubId: v.id("hubs") },
  handler: async (ctx, args) => {
    if (!(await getHubReadAccess(ctx, args.hubId))) return null;
    return await ctx.db
      .query("forecasts")
      .withIndex("by_hub_time", (q) => q.eq("hubId", args.hubId))
      .order("desc")
      .first();
  },
});

// ── Public: get forecast history for a hub ───────────────────────────────
export const getHistory = query({
  args: {
    hubId: v.id("hubs"),
    limit: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    if (!(await getHubReadAccess(ctx, args.hubId))) return [];
    return await ctx.db
      .query("forecasts")
      .withIndex("by_hub_time", (q) => q.eq("hubId", args.hubId))
      .order("desc")
      .take(Math.min(Math.max(1, args.limit ?? 7), 30));
  },
});
